// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login ログイン
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout ログアウト
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe ログイン中のユーザー
	// (GET /auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ChangeOwnPassword 自分のパスワードを変える
	// (POST /auth/password)
	ChangeOwnPassword(ctx context.Context, request ChangeOwnPasswordRequestObject) (ChangeOwnPasswordResponseObject, error)
	// ListCameras カメラの一覧
	// (GET /cameras)
	ListCameras(ctx context.Context, request ListCamerasRequestObject) (ListCamerasResponseObject, error)
	// CreateCamera カメラを登録する
	// (POST /cameras)
	CreateCamera(ctx context.Context, request CreateCameraRequestObject) (CreateCameraResponseObject, error)
	// DeleteCamera カメラを削除する
	// (DELETE /cameras/{id})
	DeleteCamera(ctx context.Context, request DeleteCameraRequestObject) (DeleteCameraResponseObject, error)
	// GetCamera カメラの設定を取得する
	// (GET /cameras/{id})
	GetCamera(ctx context.Context, request GetCameraRequestObject) (GetCameraResponseObject, error)
	// UpdateCamera カメラの設定を変える
	// (PATCH /cameras/{id})
	UpdateCamera(ctx context.Context, request UpdateCameraRequestObject) (UpdateCameraResponseObject, error)
	// GetCameraPlaylist 録画の HLS VOD プレイリスト
	// (GET /cameras/{id}/playlist.m3u8)
	GetCameraPlaylist(ctx context.Context, request GetCameraPlaylistRequestObject) (GetCameraPlaylistResponseObject, error)
	// GetCameraTimeline タイムライン用の録画の目録
	// (GET /cameras/{id}/timeline)
	GetCameraTimeline(ctx context.Context, request GetCameraTimelineRequestObject) (GetCameraTimelineResponseObject, error)
	// GetHealthz API プロセスの死活確認
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// MediamtxAuth MediaMTX の認証の問い合わせ（authMethod は http）
	// (POST /internal/mediamtx/auth)
	MediamtxAuth(ctx context.Context, request MediamtxAuthRequestObject) (MediamtxAuthResponseObject, error)
	// MediamtxSegmentComplete 録画セグメントの完了通知（MediaMTX の runOnRecordSegmentComplete）
	// (POST /internal/mediamtx/segment-complete)
	MediamtxSegmentComplete(ctx context.Context, request MediamtxSegmentCompleteRequestObject) (MediamtxSegmentCompleteResponseObject, error)
	// IssueLiveToken ライブ用のトークンを発行する
	// (POST /live/token)
	IssueLiveToken(ctx context.Context, request IssueLiveTokenRequestObject) (IssueLiveTokenResponseObject, error)
	// ListUsers ユーザーの一覧
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser ユーザーを作る
	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// DeleteUser ユーザーを削除する
	// (DELETE /users/{id})
	DeleteUser(ctx context.Context, request DeleteUserRequestObject) (DeleteUserResponseObject, error)
	// GetUser ユーザーを取得する
	// (GET /users/{id})
	GetUser(ctx context.Context, request GetUserRequestObject) (GetUserResponseObject, error)
	// UpdateUser ユーザーのロールやパスワードを変える
	// (PATCH /users/{id})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
}

